<script setup lang="ts">import { saveSettings,settings } from '../stores/diary';function toggle(key:keyof typeof settings){if(typeof settings[key]==='boolean'){(settings[key] as boolean)=!settings[key];saveSettings()}}</script>
<template><div class="page"><header class="page-header"><p class="eyebrow">YOUR SPACE</p><h1>設定</h1><p>あなたにとって、心地よい場所に。</p></header><section class="settings-group"><h2>記録のサポート</h2><button v-for="item in [{k:'notifications',i:'◷',t:'やさしい通知',d:'書きたい時間にそっとお知らせ'},{k:'location',i:'⌖',t:'位置情報',d:'市区町村までを記録'},{k:'weather',i:'☁',t:'天気の自動記録',d:'今日の空模様を添える'}]" @click="toggle(item.k as keyof typeof settings)"><span class="setting-icon">{{item.i}}</span><span><b>{{item.t}}</b><small>{{item.d}}</small></span><i class="switch" :class="{on:settings[item.k as keyof typeof settings]}"></i></button></section><section class="settings-group"><h2>見やすさ</h2><button @click="toggle('largeText')"><span class="setting-icon">文</span><span><b>文字を大きくする</b><small>読みやすいサイズで表示</small></span><i class="switch" :class="{on:settings.largeText}"></i></button><button @click="toggle('reducedMotion')"><span class="setting-icon">◌</span><span><b>動きを減らす</b><small>画面のアニメーションを控えめに</small></span><i class="switch" :class="{on:settings.reducedMotion}"></i></button></section><p class="version">DayLog prototype · 0.1.0</p></div></template>
